schema_ddl:
CREATE DOMAIN importo_monetario AS NUMERIC(14,2) CHECK (VALUE >= 0);

CREATE DOMAIN tasso_percentuale AS NUMERIC(7,4) CHECK (VALUE >= 0 AND VALUE <= 100);

CREATE TABLE conti (
    id INT PRIMARY KEY,
    iban TEXT NOT NULL UNIQUE,
    intestatario TEXT NOT NULL,
    tasso_annuo tasso_percentuale NOT NULL,
    saldo_iniziale importo_monetario NOT NULL DEFAULT 0,
    stato_conto TEXT NOT NULL DEFAULT 'attivo' CHECK (stato_conto IN ('attivo', 'sospeso', 'chiuso')),
    aperto_il DATE NOT NULL DEFAULT CURRENT_DATE
);

CREATE TABLE movimenti (
    id BIGINT PRIMARY KEY,
    conto_id INT NOT NULL REFERENCES conti(id),
    tipo_movimento TEXT NOT NULL CHECK (tipo_movimento IN ('versamento', 'prelievo', 'bonifico_entrata', 'bonifico_uscita', 'interessi_maturati', 'commissione')),
    importo importo_monetario NOT NULL,
    data_movimento DATE NOT NULL,
    descrizione TEXT,
    registrato_il TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
